import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.GameTestRequest{MaxTestsPerBatch: 100,
# Repetitions: 2, Rotation: 1, StopOnError: true,
# Position: protocol.BlockPos{1, -2, 3}, TestsPerRow: 5, Name: "mytest"}
MY_TEST = bytes.fromhex("c8010401010203060a066d7974657374")

# generated by gophertunnel b8bd735:
# packet.GameTestRequest{MaxTestsPerBatch: 300,
# Repetitions: -1, Rotation: 3, StopOnError: false,
# Position: protocol.BlockPos{0, 0, 0}, TestsPerRow: 0, Name: ""}
WIDE = bytes.fromhex("d8040103000000000000")

GOLDENS = [
    pytest.param(
        v2225.GameTestRequestPacket(
            max_tests_per_batch=100,
            repeat_count=2,
            rotation=v2225.Rotation.ROTATE_90,
            stop_on_failure=True,
            test_pos=v2225.BlockPos(x=1, y=-2, z=3),
            tests_per_row=5,
            test_name="mytest",
        ),
        MY_TEST,
        id="my-test",
    ),
    pytest.param(
        v2225.GameTestRequestPacket(
            max_tests_per_batch=300,
            repeat_count=-1,
            rotation=v2225.Rotation.ROTATE_270,
            stop_on_failure=False,
            test_pos=v2225.BlockPos(x=0, y=0, z=0),
            tests_per_row=0,
            test_name="",
        ),
        WIDE,
        id="wide-counts",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_game_test_request_is_packet_194(version):
    assert version.PACKETS[194] is version.GameTestRequestPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_game_test_request_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_game_test_request_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
